import sys

MOD = 998244353

def add(x, y):
    return ((x + y) % MOD + MOD) % MOD

def mult(x, y):
    return ((x * y) % MOD + MOD) % MOD

def exp(x, y):
    if y == 0:
        return 1
    else:
        k = exp(x, y // 2)
        if y % 2 == 0:
            return mult(k, k)
        else:
            return mult(mult(k, k), x)

def inv(x):
    return exp(x, MOD - 2)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    k = int(input_data[2])
    dp = [[0] * (k + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for i in range(k):
        for j in range(k):
            dp[i + 1][j] = add(dp[i + 1][j], mult(dp[i][j], j))
            dp[i + 1][j + 1] = add(dp[i + 1][j + 1], mult(dp[i][j], n - j))
    answer = 0
    inv_m = inv(m)
    for i in range(1, k + 1):
        answer = add(answer, mult(dp[k][i], exp(inv_m, i)))
    print(answer)

if __name__ == "__main__":
    main()

